/* @lc app=leetcode id=2056 lang=kotlin */ class Solution { fun mv(p: String, pos: IntArray): List<IntArray> = (if (p == "rook") listOf(1 to 0, -1 to 0, 0 to 1, 0 to -1) else if (p == "bishop") listOf(1 to 1, 1 to -1, -1 to 1, -1 to -1) else listOf(1 to 0, -1 to 0, 0 to 1, 0 to -1, 1 to 1, 1 to -1, -1 to 1, -1 to -1)).flatMap { (dr, dc) -> (1..7).takeWhile { pos[0] + dr * it in 1..8 && pos[1] + dc * it in 1..8 }.map { intArrayOf(pos[0], pos[1], dr, dc, it) } } + listOf(intArrayOf(pos[0], pos[1], 0, 0, 0)) fun ok(a: IntArray, b: IntArray): Boolean = (0..7).all { t -> minOf(t, a[4]).let { x -> minOf(t, b[4]).let { y -> a[0] + a[2] * x != b[0] + b[2] * y || a[1] + a[3] * x != b[1] + b[3] * y } } } fun countCombinations(pieces: Array<String>, positions: Array<IntArray>): Int = pieces.indices.map { mv(pieces[it], positions[it]) }.let { m -> pieces.indices.fold(listOf(listOf<IntArray>())) { acc, i -> acc.flatMap { sel -> m[i].filter { x -> sel.all { ok(it, x) } }.map { x -> sel + listOf(x) } } }.size } }